    public void testUTF8() throws GeneralSecurityException, IOException {
        String plaintxt = "火尸木火1十寥日烤";
        SecretKey key = generateKey("AES");

        byte[] plaintxt_encoded = plaintxt.getBytes();

        SecretKey plaintxt_key = new SecretKeySpec(plaintxt_encoded, "AES");
        EncryptedKey ek = EncryptedKey.encrypt(key, plaintxt_key);

        SecretKey sk = ek.decrypt(key);
        byte[] decryptedBytes = sk.getEncoded();
        String decryptedText = new String(decryptedBytes, StandardCharsets.UTF_8);

        assertEquals(plaintxt, decryptedText);
    }

    @Test
    public void testExplicitGcmRoundTripRetainsParametersAndAad() throws GeneralSecurityException, IOException {
        SecretKey encryptionKey = generateKey("AES");
        SecretKey hmacKey = generateKey("HmacSHA512");
        SecretKey aesKey = generateKey("AES");

        EncryptedKey encryptedHmacKey = EncryptedKey.encrypt(encryptionKey, hmacKey);
        EncryptedKey encryptedAesKey = EncryptedKey.encrypt(encryptionKey, aesKey);

        SecretKey decryptedHmacKey = encryptedHmacKey.decrypt(encryptionKey);
        SecretKey decryptedAesKey = encryptedAesKey.decrypt(encryptionKey);

        Assert.assertArrayEquals(hmacKey.getEncoded(), decryptedHmacKey.getEncoded());
        assertEquals(hmacKey.getAlgorithm(), decryptedHmacKey.getAlgorithm());
        Assert.assertArrayEquals(aesKey.getEncoded(), decryptedAesKey.getEncoded());
        assertEquals(aesKey.getAlgorithm(), decryptedAesKey.getAlgorithm());
    }","reason":"Adds public-interface coverage for two independent encrypted records using the explicit-GCM EncryptedKey implementation. Successful decryption verifies the retained encryption parameters remain consumable, and the encoding and algorithm assertions verify the existing AAD-protected restoration contract without depending on fresh random values." ,"symbol":"EncryptedKeyTest encryption/decryption test cases"}],"manual_review_required":true,"provided_contracts":["EncryptedKeyTest preserves the existing encoding-equality, algorithm-equality, and UTF-8 round-trip assertions unchanged.","EncryptedKeyTest additionally verifies independent EncryptedKey.encrypt/decrypt round trips preserve protected-key encodings and algorithms for HmacSHA512 and AES protected keys."],"required_contracts":["EncryptedKey.encrypt retains its public name, parameter order, return type, and checked-exception contract.","EncryptedKey.encrypt uses explicit fresh AES/GCM parameters, retains decryptable AlgorithmParameters, and authenticates the protected-key algorithm as AAD.","Supported Android providers must decode retained AES/GCM AlgorithmParameters during EncryptedKey.decrypt."],"source_file_path":"mobile/src/androidTest/java/org/fedorahosted/freeotp/EncryptedKeyTest.java","required_tests":["Compile mobile androidTest sources.","Run EncryptedKeyTest on supported Android providers and confirm all existing and added round-trip assertions pass.","Run coordinated MasterKeyTest and KeyStoreAccessTest instrumentation coverage after the production changes are assembled."]}
